import{_ as o,o as a,c as l,a2 as c}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_controller_cover.png",t="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_controller_01_architecture.png",i="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_controller_02_lifecycle.png",d="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_controller_03_plugins.png",n="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_controller_05_interfaces.png",h="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_controller_04_control_loop.png",s="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_controller_06_outcomes.png",g=JSON.parse('{"title":"一条路径如何变成速度？拆解 nav2_controller 的插件矩阵与闭环数据流","description":"全局规划器给出一条 Path，机器人却不能直接“沿线走”。真正让底盘动起来的，是一个持续重复的闭环：读取当前位姿和速度，观察局部障碍，选择控制算法，计算速度，检查是否仍在前进，再判断是否到达目标。","frontmatter":{"title":"一条路径如何变成速度？拆解 `nav2_controller` 的插件矩阵与闭环数据流","description":"全局规划器给出一条 Path，机器人却不能直接“沿线走”。真正让底盘动起来的，是一个持续重复的闭环：读取当前位姿和速度，观察局部障碍，选择控制算法，计算速度，检查是否仍在前进，再判断是否到达目标。","date":"2026-07-17","section":"三 · 局部控制与速度生成","readingTime":16,"source":"2026-07-17/nav2_controller_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-17/nav2_controller_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-controller-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一条路径如何变成速度？拆解 `nav2_controller` 的插件矩阵与闭环数据流"}],["meta",{"property":"og:description","content":"全局规划器给出一条 Path，机器人却不能直接“沿线走”。真正让底盘动起来的，是一个持续重复的闭环：读取当前位姿和速度，观察局部障碍，选择控制算法，计算速度，检查是否仍在前进，再判断是否到达目标。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-controller-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-17/nav2_controller_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-17"}],["meta",{"name":"twitter:title","content":"一条路径如何变成速度？拆解 `nav2_controller` 的插件矩阵与闭环数据流"}],["meta",{"name":"twitter:description","content":"全局规划器给出一条 Path，机器人却不能直接“沿线走”。真正让底盘动起来的，是一个持续重复的闭环：读取当前位姿和速度，观察局部障碍，选择控制算法，计算速度，检查是否仍在前进，再判断是否到达目标。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-17/nav2_controller_cover.png"}]],"prev":{"text":"一张拓扑图如何变成可执行路线？逐函数拆解 Nav2 Route Server 的 241 个入口","link":"/nav2/nav2-route-241-functions-source-walkthrough"},"next":{"text":"每 50 毫秒“试跑”420 条未来，机器人为什么只执行这一条？拆解 Nav2 DWB 全调用、状态与数据流","link":"/nav2/nav2-dwb-controller-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-controller-full-dataflow.md","filePath":"nav2/nav2-controller-full-dataflow.md","lastUpdated":null}'),p={name:"nav2/nav2-controller-full-dataflow.md"};function _(u,e,m,b,k,C){return a(),l("div",null,[...e[0]||(e[0]=[c('<h1 id="一条路径如何变成速度-拆解-nav2-controller-的插件矩阵与闭环数据流" tabindex="-1">一条路径如何变成速度？拆解 <code>nav2_controller</code> 的插件矩阵与闭环数据流 <a class="header-anchor" href="#一条路径如何变成速度-拆解-nav2-controller-的插件矩阵与闭环数据流" aria-label="Permalink to &quot;一条路径如何变成速度？拆解 `nav2_controller` 的插件矩阵与闭环数据流&quot;">​</a></h1><p><img src="'+r+'" alt="封面：nav2_controller 从路径到速度的闭环控制"></p><p>全局规划器给出一条 <code>Path</code>，机器人却不能直接“沿线走”。真正让底盘动起来的，是一个持续重复的闭环：读取当前位姿和速度，观察局部障碍，选择控制算法，计算速度，检查是否仍在前进，再判断是否到达目标。</p><p>在 Nav2 中，这个闭环由 <code>nav2_controller</code> 承担。</p><p>它不是某一种局部规划算法，也不等同于 DWB、RPP 或 MPPI。更准确地说，<code>nav2_controller</code> 是一个具备 Lifecycle、Action、局部代价地图和插件调度能力的控制任务服务器。它把不同控制算法、进度判定和到达判定统一装进 <code>/follow_path</code> 这条标准接口。</p><p>本文基于当前工程中的 <code>nav2_controller 1.1.20</code> 源码，完整拆解它的调用关系、三层状态、插件体系，以及从路径输入到速度输出的数据流。</p><hr><h2 id="一、先给结论-controller-server-是控制闭环的-运行时容器" tabindex="-1">一、先给结论：Controller Server 是控制闭环的“运行时容器” <a class="header-anchor" href="#一、先给结论-controller-server-是控制闭环的-运行时容器" aria-label="Permalink to &quot;一、先给结论：Controller Server 是控制闭环的“运行时容器”&quot;">​</a></h2><p><code>nav2_controller</code> 的核心节点是 <code>ControllerServer</code>。它做六件事：</p><ul><li>对上提供 <code>nav2_msgs/action/FollowPath</code> Action。</li><li>接收全局路径，并按 Goal 中的 ID 选择 Controller 和 Goal Checker。</li><li>自己持有并运行一个 <code>local_costmap</code>。</li><li>从 TF 获取机器人位姿，从 <code>/odom</code> 获取机器人速度。</li><li>调用 Controller 插件计算 <code>cmd_vel</code>。</li><li>用 Progress Checker 识别“卡住”，用 Goal Checker 判断“到达”。</li></ul><p>所以它在导航栈中的位置不是“路径规划”，而是“路径执行”。</p><p><img src="'+t+'" alt="图 1：nav2_controller 在导航链路中的位置"></p><p>上游可以有多种调用者：</p><ul><li>标准 Nav2 中，行为树的 <code>FollowPath</code> 节点调用 <code>/follow_path</code>。</li><li>本项目取消行为树后，<code>RegulatedNavigator</code> 直接作为 Action Client 调用 <code>/follow_path</code>。</li><li><code>nav2_simple_commander</code> 也可以绕过完整导航编排，直接发送已知路径。</li></ul><p>下游同样可以变化。源码发布的逻辑名称是 <code>cmd_vel</code>，标准 Bringup 和本项目的规控 Launch 都把它重映射为 <code>cmd_vel_nav</code>，再交给 Velocity Smoother 输出最终 <code>/cmd_vel</code>。</p><p>这说明 <code>ControllerServer</code> 的边界很清楚：它负责产生原始导航速度，不负责全局规划，也不负责最后一级底盘通信。</p><hr><h2 id="二、第一层状态-lifecycle-决定控制能力是否存在" tabindex="-1">二、第一层状态：Lifecycle 决定控制能力是否存在 <a class="header-anchor" href="#二、第一层状态-lifecycle-决定控制能力是否存在" aria-label="Permalink to &quot;二、第一层状态：Lifecycle 决定控制能力是否存在&quot;">​</a></h2><p><code>ControllerServer</code> 继承 <code>nav2_util::LifecycleNode</code>。它的资源不是在构造函数里一次性全部创建，而是跟随 ROS 2 Lifecycle 分阶段建立、激活和释放。</p><p><img src="'+i+'" alt="图 2：ControllerServer 生命周期与资源边界"></p><h3 id="_2-1-unconfigured-只有节点骨架" tabindex="-1">2.1 UNCONFIGURED：只有节点骨架 <a class="header-anchor" href="#_2-1-unconfigured-只有节点骨架" aria-label="Permalink to &quot;2.1 UNCONFIGURED：只有节点骨架&quot;">​</a></h3><p>构造函数完成服务器级参数声明，建立三个 Pluginlib Loader，并创建名为 <code>local_costmap</code> 的 <code>Costmap2DROS</code> 对象。</p><p>此时还不能接收 <code>FollowPath</code> 目标，也不会发布速度。</p><p>默认插件类型在这一阶段确定：</p><ul><li>默认 Progress Checker：<code>nav2_controller::SimpleProgressChecker</code>。</li><li>默认 Goal Checker：<code>nav2_controller::SimpleGoalChecker</code>。</li><li>默认 Controller：<code>dwb_core::DWBLocalPlanner</code>。</li></ul><p>注意，DWB 只是默认加载类型，不是 <code>nav2_controller</code> 包自己导出的插件。</p><h3 id="_2-2-on-configure-把控制系统装起来" tabindex="-1">2.2 on_configure：把控制系统装起来 <a class="header-anchor" href="#_2-2-on-configure-把控制系统装起来" aria-label="Permalink to &quot;2.2 on_configure：把控制系统装起来&quot;">​</a></h3><p><code>on_configure()</code> 的主要调用顺序如下。</p><h4 id="_2-2-1-读取插件参数" tabindex="-1">2.2.1 读取插件参数 <a class="header-anchor" href="#_2-2-1-读取插件参数" aria-label="Permalink to &quot;2.2.1 读取插件参数&quot;">​</a></h4><p>读取 <code>progress_checker_plugin</code>、<code>goal_checker_plugins</code>、<code>controller_plugins</code>。</p><h4 id="_2-2-2-配置-local-costmap" tabindex="-1">2.2.2 配置 Local Costmap <a class="header-anchor" href="#_2-2-2-配置-local-costmap" aria-label="Permalink to &quot;2.2.2 配置 Local Costmap&quot;">​</a></h4><p>配置内部 <code>local_costmap</code>，并用独立 <code>NodeThread</code> 运行它。</p><h4 id="_2-2-3-创建-progress-checker" tabindex="-1">2.2.3 创建 Progress Checker <a class="header-anchor" href="#_2-2-3-创建-progress-checker" aria-label="Permalink to &quot;2.2.3 创建 Progress Checker&quot;">​</a></h4><p>创建 Progress Checker 实例。</p><h4 id="_2-2-4-创建-goal-checker" tabindex="-1">2.2.4 创建 Goal Checker <a class="header-anchor" href="#_2-2-4-创建-goal-checker" aria-label="Permalink to &quot;2.2.4 创建 Goal Checker&quot;">​</a></h4><p>创建一个或多个 Goal Checker 实例。</p><h4 id="_2-2-5-创建-controller" tabindex="-1">2.2.5 创建 Controller <a class="header-anchor" href="#_2-2-5-创建-controller" aria-label="Permalink to &quot;2.2.5 创建 Controller&quot;">​</a></h4><p>创建一个或多个 Controller 实例，并把 TF Buffer 和 <code>Costmap2DROS</code> 共享指针传进去。</p><h4 id="_2-2-6-创建-odom-订阅" tabindex="-1">2.2.6 创建 Odom 订阅 <a class="header-anchor" href="#_2-2-6-创建-odom-订阅" aria-label="Permalink to &quot;2.2.6 创建 Odom 订阅&quot;">​</a></h4><p>创建 <code>/odom</code> 订阅。</p><h4 id="_2-2-7-创建速度发布器" tabindex="-1">2.2.7 创建速度发布器 <a class="header-anchor" href="#_2-2-7-创建速度发布器" aria-label="Permalink to &quot;2.2.7 创建速度发布器&quot;">​</a></h4><p>创建 Lifecycle <code>cmd_vel</code> Publisher。</p><h4 id="_2-2-8-创建-followpath-action-server" tabindex="-1">2.2.8 创建 FollowPath Action Server <a class="header-anchor" href="#_2-2-8-创建-followpath-action-server" aria-label="Permalink to &quot;2.2.8 创建 FollowPath Action Server&quot;">​</a></h4><p>创建 <code>/follow_path</code> Action Server。</p><h4 id="_2-2-9-创建限速订阅" tabindex="-1">2.2.9 创建限速订阅 <a class="header-anchor" href="#_2-2-9-创建限速订阅" aria-label="Permalink to &quot;2.2.9 创建限速订阅&quot;">​</a></h4><p>创建 <code>speed_limit</code> 订阅。</p><p>配置完成后进入 INACTIVE。资源已经存在，但 Action Server 和速度 Publisher 还没有进入工作状态。</p><h3 id="_2-3-on-activate-开始接受路径" tabindex="-1">2.3 on_activate：开始接受路径 <a class="header-anchor" href="#_2-3-on-activate-开始接受路径" aria-label="Permalink to &quot;2.3 on_activate：开始接受路径&quot;">​</a></h3><p>激活顺序如下。</p><h4 id="_2-3-1-激活-local-costmap" tabindex="-1">2.3.1 激活 Local Costmap <a class="header-anchor" href="#_2-3-1-激活-local-costmap" aria-label="Permalink to &quot;2.3.1 激活 Local Costmap&quot;">​</a></h4><p>激活 <code>local_costmap</code>。</p><h4 id="_2-3-2-激活-controller" tabindex="-1">2.3.2 激活 Controller <a class="header-anchor" href="#_2-3-2-激活-controller" aria-label="Permalink to &quot;2.3.2 激活 Controller&quot;">​</a></h4><p>逐个激活 Controller 插件。</p><h4 id="_2-3-3-激活速度发布器" tabindex="-1">2.3.3 激活速度发布器 <a class="header-anchor" href="#_2-3-3-激活速度发布器" aria-label="Permalink to &quot;2.3.3 激活速度发布器&quot;">​</a></h4><p>激活 <code>cmd_vel</code> Lifecycle Publisher。</p><h4 id="_2-3-4-激活-followpath" tabindex="-1">2.3.4 激活 FollowPath <a class="header-anchor" href="#_2-3-4-激活-followpath" aria-label="Permalink to &quot;2.3.4 激活 FollowPath&quot;">​</a></h4><p>激活 <code>/follow_path</code> Action Server。</p><h4 id="_2-3-5-注册动态参数回调" tabindex="-1">2.3.5 注册动态参数回调 <a class="header-anchor" href="#_2-3-5-注册动态参数回调" aria-label="Permalink to &quot;2.3.5 注册动态参数回调&quot;">​</a></h4><p>注册服务器级动态参数回调。</p><h4 id="_2-3-6-建立-bond" tabindex="-1">2.3.6 建立 Bond <a class="header-anchor" href="#_2-3-6-建立-bond" aria-label="Permalink to &quot;2.3.6 建立 Bond&quot;">​</a></h4><p>与 Lifecycle Manager 建立 Bond。</p><p>此时节点进入 ACTIVE，才真正具备闭环控制能力。</p><h3 id="_2-4-on-deactivate-先停任务-再停速度" tabindex="-1">2.4 on_deactivate：先停任务，再停速度 <a class="header-anchor" href="#_2-4-on-deactivate-先停任务-再停速度" aria-label="Permalink to &quot;2.4 on_deactivate：先停任务，再停速度&quot;">​</a></h3><p>停用阶段会先停 Action Server，再停 Controller 插件和 <code>local_costmap</code>，随后发布一次零速度，最后停用速度 Publisher、移除动态参数回调并断开 Bond。</p><p>这个顺序表达了一个重要安全原则：控制能力退出前，先让正在执行的任务失效，并尝试把速度收敛到零。</p><h3 id="_2-5-on-cleanup-释放运行资源" tabindex="-1">2.5 on_cleanup：释放运行资源 <a class="header-anchor" href="#_2-5-on-cleanup-释放运行资源" aria-label="Permalink to &quot;2.5 on_cleanup：释放运行资源&quot;">​</a></h3><p>Cleanup 会清理 Controller、Goal Checker、Costmap、Action Server、Odom Subscriber、Costmap Thread、速度 Publisher 和 Speed Limit Subscriber，使节点重新回到 UNCONFIGURED。</p><p><code>on_shutdown()</code> 在当前实现中只记录停机日志，不承担额外资源编排。</p><hr><h2 id="三、第二层状态-三类插件各自回答一个问题" tabindex="-1">三、第二层状态：三类插件各自回答一个问题 <a class="header-anchor" href="#三、第二层状态-三类插件各自回答一个问题" aria-label="Permalink to &quot;三、第二层状态：三类插件各自回答一个问题&quot;">​</a></h2><p>Controller Server 同时管理三类插件，但三类插件的职责不能混淆。</p><p><img src="'+d+'" alt="图 3：Controller、Progress Checker 与 Goal Checker 插件体系"></p><h3 id="_3-1-controller-下一帧速度应该是多少" tabindex="-1">3.1 Controller：下一帧速度应该是多少？ <a class="header-anchor" href="#_3-1-controller-下一帧速度应该是多少" aria-label="Permalink to &quot;3.1 Controller：下一帧速度应该是多少？&quot;">​</a></h3><p>Controller 插件实现 <code>nav2_core::Controller</code>，核心接口包括：</p><ul><li><code>configure()</code>：获得父节点、插件名、TF Buffer 和 Costmap。</li><li><code>setPlan()</code>：接收当前要执行的全局路径。</li><li><code>computeVelocityCommands()</code>：根据当前位姿、当前速度和 Goal Checker 计算速度。</li><li><code>setSpeedLimit()</code>：接收绝对速度或百分比限速。</li><li><code>activate()</code>、<code>deactivate()</code>、<code>cleanup()</code>：跟随服务器生命周期。</li></ul><p><code>nav2_controller</code> 包本身没有在 <code>plugins.xml</code> 中导出任何 Controller 算法。DWB、RPP、MPPI、TEB 等都来自其他包，通过相同基类被 Controller Server 加载。</p><p>当前项目的 <code>regulated_modules.yaml</code> 一次加载五个 Controller：</p><ul><li><code>DWB</code>：轨迹采样并用 Critic 打分。</li><li><code>RPP</code>：受约束纯跟踪，按曲率、障碍和接近目标状态调速。</li><li><code>MPPI</code>：批量采样控制序列并用代价函数优化。</li><li><code>GracefulController</code>：用平滑姿态控制律收敛到路径和目标姿态。</li><li><code>RotationShimController</code>：先对齐路径初始方向，再委托内部主控制器跟踪。</li></ul><p>工程的 <code>myworld2.yaml</code> 还加载了 <code>TEB</code>。这些是“Controller Server 托管的插件”，不是“本包源码实现的插件”。</p><h3 id="_3-2-progress-checker-机器人是否在规定时间内取得进展" tabindex="-1">3.2 Progress Checker：机器人是否在规定时间内取得进展？ <a class="header-anchor" href="#_3-2-progress-checker-机器人是否在规定时间内取得进展" aria-label="Permalink to &quot;3.2 Progress Checker：机器人是否在规定时间内取得进展？&quot;">​</a></h3><p>本包导出两个 Progress Checker。</p><h4 id="_3-2-1-simpleprogresschecker" tabindex="-1">3.2.1 SimpleProgressChecker <a class="header-anchor" href="#_3-2-1-simpleprogresschecker" aria-label="Permalink to &quot;3.2.1 SimpleProgressChecker&quot;">​</a></h4><p>它保存一个基准位姿和基准时间。如果机器人相对基准点移动超过 <code>required_movement_radius</code>，就更新基准并返回成功；如果一直没有移动到要求距离，且超过 <code>movement_time_allowance</code>，则返回失败。</p><p>默认值分别是 <code>0.5 m</code> 和 <code>10 s</code>。</p><h4 id="_3-2-2-poseprogresschecker" tabindex="-1">3.2.2 PoseProgressChecker <a class="header-anchor" href="#_3-2-2-poseprogresschecker" aria-label="Permalink to &quot;3.2.2 PoseProgressChecker&quot;">​</a></h4><p>它继承 SimpleProgressChecker，并增加 <code>required_movement_angle</code>。只要平移距离或旋转角度有一个超过阈值，就认为机器人取得了进展。</p><p>这对“允许原地旋转也是有效动作”的底盘更合理，避免机器人明明正在调整航向，却被纯平移判定误认为卡死。</p><h3 id="_3-3-goal-checker-机器人是否已经到达" tabindex="-1">3.3 Goal Checker：机器人是否已经到达？ <a class="header-anchor" href="#_3-3-goal-checker-机器人是否已经到达" aria-label="Permalink to &quot;3.3 Goal Checker：机器人是否已经到达？&quot;">​</a></h3><p>本包导出三个 Goal Checker。</p><h4 id="_3-3-1-simplegoalchecker" tabindex="-1">3.3.1 SimpleGoalChecker <a class="header-anchor" href="#_3-3-1-simplegoalchecker" aria-label="Permalink to &quot;3.3.1 SimpleGoalChecker&quot;">​</a></h4><p>同时检查 XY 位置误差和 Yaw 航向误差。<code>stateful=true</code> 时，一旦 XY 进入容差范围，后续只继续检查航向，不会因为末端旋转时位置轻微漂移而退回位置阶段。</p><p>当前源码还支持 <code>symmetric_yaw_tolerance</code>。启用后，对称机器人既可以匹配目标航向，也可以匹配目标航向加 180°。</p><h4 id="_3-3-2-stoppedgoalchecker" tabindex="-1">3.3.2 StoppedGoalChecker <a class="header-anchor" href="#_3-3-2-stoppedgoalchecker" aria-label="Permalink to &quot;3.3.2 StoppedGoalChecker&quot;">​</a></h4><p>先复用 SimpleGoalChecker 的位置与航向判断，再额外检查平移速度和旋转速度是否低于阈值。适合“进入目标框还不算结束，必须真正停稳”的任务。</p><h4 id="_3-3-3-positiongoalchecker" tabindex="-1">3.3.3 PositionGoalChecker <a class="header-anchor" href="#_3-3-3-positiongoalchecker" aria-label="Permalink to &quot;3.3.3 PositionGoalChecker&quot;">​</a></h4><p>只检查 XY 位置，完全忽略目标朝向。<code>stateful=true</code> 时，一旦进入位置容差就保持到达状态。</p><p>这里还要区分两个名字：</p><ul><li>Plugin ID 是参数和 Action Goal 中使用的实例名，例如 <code>general_goal_checker</code>、<code>DWB</code>。</li><li>Plugin Type 是 Pluginlib 加载的 C++ 类型，例如 <code>nav2_controller::SimpleGoalChecker</code>、<code>dwb_core::DWBLocalPlanner</code>。</li></ul><p>Action 传错的是 ID 时，即使对应 Type 已经安装，Controller Server 仍会拒绝该目标。</p><hr><h2 id="四、输入输出接口-一条-action-串起五类数据" tabindex="-1">四、输入输出接口：一条 Action 串起五类数据 <a class="header-anchor" href="#四、输入输出接口-一条-action-串起五类数据" aria-label="Permalink to &quot;四、输入输出接口：一条 Action 串起五类数据&quot;">​</a></h2><p><img src="'+n+'" alt="图 4：ControllerServer 输入输出接口全景"></p><h3 id="_4-1-action-输入-follow-path" tabindex="-1">4.1 Action 输入：<code>/follow_path</code> <a class="header-anchor" href="#_4-1-action-输入-follow-path" aria-label="Permalink to &quot;4.1 Action 输入：`/follow_path`&quot;">​</a></h3><p>类型为 <code>nav2_msgs/action/FollowPath</code>。</p><p>Goal 包含：</p><ul><li><code>path</code>：<code>nav_msgs/Path</code>，要执行的路径。</li><li><code>controller_id</code>：本次任务选择的 Controller Plugin ID。</li><li><code>goal_checker_id</code>：本次任务选择的 Goal Checker Plugin ID。</li></ul><p>如果只加载一个 Controller 或 Goal Checker，且 Goal 中 ID 为空，服务器会自动使用唯一实例并输出一次警告；如果加载了多个插件却不给有效 ID，目标会失败。</p><h3 id="_4-2-action-输出-feedback-与终态" tabindex="-1">4.2 Action 输出：Feedback 与终态 <a class="header-anchor" href="#_4-2-action-输出-feedback-与终态" aria-label="Permalink to &quot;4.2 Action 输出：Feedback 与终态&quot;">​</a></h3><p>Feedback 包含：</p><ul><li><code>distance_to_goal</code>：从当前路径中距离机器人最近的路径点开始，累加到路径末端的剩余路径长度。</li><li><code>speed</code>：本周期 Controller 输出指令的平面线速度模长。</li></ul><p>这里有两个常见误解。</p><h4 id="_4-2-1-distance-to-goal-的含义" tabindex="-1">4.2.1 <code>distance_to_goal</code> 的含义 <a class="header-anchor" href="#_4-2-1-distance-to-goal-的含义" aria-label="Permalink to &quot;4.2.1 `distance_to_goal` 的含义&quot;">​</a></h4><p><code>distance_to_goal</code> 不是机器人到目标点的直线距离，而是沿当前路径计算的剩余长度。</p><h4 id="_4-2-2-speed-的含义" tabindex="-1">4.2.2 <code>speed</code> 的含义 <a class="header-anchor" href="#_4-2-2-speed-的含义" aria-label="Permalink to &quot;4.2.2 `speed` 的含义&quot;">​</a></h4><p><code>speed</code> 来自本周期计算出的速度指令，不是 <code>/odom</code> 中测得的真实车速。</p><p>当前版本的 Result 负载只有一个空消息，真正的结果信息依赖 Action 终态：<code>SUCCEEDED</code>、<code>ABORTED</code> 或 <code>CANCELED</code>。失败原因主要从 Controller Server 日志和上层恢复逻辑获得。</p><h3 id="_4-3-topic-输入-odom" tabindex="-1">4.3 Topic 输入：<code>/odom</code> <a class="header-anchor" href="#_4-3-topic-输入-odom" aria-label="Permalink to &quot;4.3 Topic 输入：`/odom`&quot;">​</a></h3><p><code>OdomSubscriber</code> 默认订阅相对名称 <code>odom</code>，消息类型为 <code>nav_msgs/Odometry</code>。</p><p>Controller Server只取：</p><ul><li><code>twist.twist.linear.x</code>。</li><li><code>twist.twist.linear.y</code>。</li><li><code>twist.twist.angular.z</code>。</li></ul><p>随后用 <code>min_x_velocity_threshold</code>、<code>min_y_velocity_threshold</code> 和 <code>min_theta_velocity_threshold</code> 把微小速度压成零，再传给 Controller 和 Goal Checker。</p><p>Odom 在这里提供的是“当前运动速度”，机器人位姿并不从 Odom 消息直接读取。</p><h3 id="_4-4-topic-输入-speed-limit" tabindex="-1">4.4 Topic 输入：<code>speed_limit</code> <a class="header-anchor" href="#_4-4-topic-输入-speed-limit" aria-label="Permalink to &quot;4.4 Topic 输入：`speed_limit`&quot;">​</a></h3><p>默认 Topic 名称为相对名称 <code>speed_limit</code>，类型为 <code>nav2_msgs/SpeedLimit</code>。</p><p>收到消息后，Controller Server 会遍历所有已加载 Controller，逐个调用 <code>setSpeedLimit(speed_limit, percentage)</code>。因此限速不是只作用于当前 Controller，而是同步更新全部已加载实例，方便后续切换插件时保持一致的限速状态。</p><h3 id="_4-5-tf-与-local-costmap-输入" tabindex="-1">4.5 TF 与 Local Costmap 输入 <a class="header-anchor" href="#_4-5-tf-与-local-costmap-输入" aria-label="Permalink to &quot;4.5 TF 与 Local Costmap 输入&quot;">​</a></h3><p><code>ControllerServer</code> 自己持有 <code>local_costmap</code>。当前位姿通过 <code>costmap_ros_-&gt;getRobotPose()</code> 获取，Controller 插件同时得到 Costmap 和 TF Buffer 的共享指针。</p><p>因此控制闭环实际依赖：</p><ul><li>TF 中从 Costmap Global Frame 到 Robot Base Frame 的可用变换。</li><li>Local Costmap 当前有效。</li><li>障碍层、膨胀层、Footprint 等局部环境信息已经更新。</li></ul><p>源码在每个循环开始前检查 <code>costmap_ros_-&gt;isCurrent()</code>。清图或传感器更新期间，如果 Costmap 还没有恢复为当前状态，控制计算会等待，而不是使用过期地图直接出速度。</p><h3 id="_4-6-topic-输出-cmd-vel" tabindex="-1">4.6 Topic 输出：<code>cmd_vel</code> <a class="header-anchor" href="#_4-6-topic-输出-cmd-vel" aria-label="Permalink to &quot;4.6 Topic 输出：`cmd_vel`&quot;">​</a></h3><p>源码创建 <code>geometry_msgs/Twist</code> 的 Lifecycle Publisher，逻辑 Topic 为 <code>cmd_vel</code>。</p><p>本项目把它重映射为 <code>cmd_vel_nav</code>，随后形成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Controller Server /cmd_vel_nav</span></span>\n<span class="line"><span>  -&gt; Velocity Smoother /cmd_vel</span></span>\n<span class="line"><span>  -&gt; controlpub /control_to_uart</span></span>\n<span class="line"><span>  -&gt; 底盘</span></span></code></pre></div><p><code>publishVelocity()</code> 只有在 Publisher 已激活且至少存在一个订阅者时才真正发布。这意味着下游控制链未连接时，日志里即使完成了速度计算，也可能看不到 <code>cmd_vel</code> 消息。</p><hr><h2 id="五、核心调用链-一帧-cmd-vel-是怎样生成的" tabindex="-1">五、核心调用链：一帧 <code>cmd_vel</code> 是怎样生成的 <a class="header-anchor" href="#五、核心调用链-一帧-cmd-vel-是怎样生成的" aria-label="Permalink to &quot;五、核心调用链：一帧 `cmd_vel` 是怎样生成的&quot;">​</a></h2><p><code>/follow_path</code> 的执行回调是 <code>computeControl()</code>。它持有服务器级动态参数互斥锁，并按 <code>controller_frequency</code> 循环调用控制函数。</p><p><img src="'+h+`" alt="图 5：FollowPath 控制循环"></p><p>完整调用顺序如下。</p><h3 id="_5-1-接收-goal-并选插件" tabindex="-1">5.1 接收 Goal 并选插件 <a class="header-anchor" href="#_5-1-接收-goal-并选插件" aria-label="Permalink to &quot;5.1 接收 Goal 并选插件&quot;">​</a></h3><p><code>computeControl()</code> 读取 <code>controller_id</code> 和 <code>goal_checker_id</code>，分别调用 <code>findControllerId()</code> 与 <code>findGoalCheckerId()</code>。</p><p>ID 有效后，进入 <code>setPlannerPath()</code>。</p><h4 id="_5-1-1-拒绝空路径" tabindex="-1">5.1.1 拒绝空路径 <a class="header-anchor" href="#_5-1-1-拒绝空路径" aria-label="Permalink to &quot;5.1.1 拒绝空路径&quot;">​</a></h4><p>拒绝空路径。</p><h4 id="_5-1-2-下发路径" tabindex="-1">5.1.2 下发路径 <a class="header-anchor" href="#_5-1-2-下发路径" aria-label="Permalink to &quot;5.1.2 下发路径&quot;">​</a></h4><p>调用当前 Controller 的 <code>setPlan(path)</code>。</p><h4 id="_5-1-3-保存终点" tabindex="-1">5.1.3 保存终点 <a class="header-anchor" href="#_5-1-3-保存终点" aria-label="Permalink to &quot;5.1.3 保存终点&quot;">​</a></h4><p>保存路径终点到 <code>end_pose_</code>。</p><h4 id="_5-1-4-重置-goal-checker" tabindex="-1">5.1.4 重置 Goal Checker <a class="header-anchor" href="#_5-1-4-重置-goal-checker" aria-label="Permalink to &quot;5.1.4 重置 Goal Checker&quot;">​</a></h4><p>Reset 当前 Goal Checker。</p><h4 id="_5-1-5-保存当前路径" tabindex="-1">5.1.5 保存当前路径 <a class="header-anchor" href="#_5-1-5-保存当前路径" aria-label="Permalink to &quot;5.1.5 保存当前路径&quot;">​</a></h4><p>保存路径到 <code>current_path_</code>。</p><p>新任务开始时还会 Reset Progress Checker，清空上一任务的进度基线。</p><h3 id="_5-2-等待-costmap-可用" tabindex="-1">5.2 等待 Costmap 可用 <a class="header-anchor" href="#_5-2-等待-costmap-可用" aria-label="Permalink to &quot;5.2 等待 Costmap 可用&quot;">​</a></h3><p>控制循环以 <code>100 Hz</code> 检查 <code>local_costmap</code> 是否 Current。只有地图有效后才进入本周期计算。</p><h3 id="_5-3-处理新路径抢占" tabindex="-1">5.3 处理新路径抢占 <a class="header-anchor" href="#_5-3-处理新路径抢占" aria-label="Permalink to &quot;5.3 处理新路径抢占&quot;">​</a></h3><p><code>updateGlobalPath()</code> 检查 Action Server 是否存在 Pending Goal。</p><p>如果有新目标，则按以下步骤处理。</p><h4 id="_5-3-1-接受-pending-goal" tabindex="-1">5.3.1 接受 Pending Goal <a class="header-anchor" href="#_5-3-1-接受-pending-goal" aria-label="Permalink to &quot;5.3.1 接受 Pending Goal&quot;">​</a></h4><p>接受 Pending Goal。</p><h4 id="_5-3-2-重新选择插件" tabindex="-1">5.3.2 重新选择插件 <a class="header-anchor" href="#_5-3-2-重新选择插件" aria-label="Permalink to &quot;5.3.2 重新选择插件&quot;">​</a></h4><p>重新选择 Controller 和 Goal Checker。</p><h4 id="_5-3-3-替换路径" tabindex="-1">5.3.3 替换路径 <a class="header-anchor" href="#_5-3-3-替换路径" aria-label="Permalink to &quot;5.3.3 替换路径&quot;">​</a></h4><p>调用 <code>setPlannerPath()</code> 替换路径。</p><h4 id="_5-3-4-重置-goal-checker" tabindex="-1">5.3.4 重置 Goal Checker <a class="header-anchor" href="#_5-3-4-重置-goal-checker" aria-label="Permalink to &quot;5.3.4 重置 Goal Checker&quot;">​</a></h4><p>Reset Goal Checker。</p><p>这里不会 Reset Progress Checker，所以抢占更新路径后，进度检查仍沿用当前 FollowPath 执行过程的基线。</p><h3 id="_5-4-获取当前位姿并检查进展" tabindex="-1">5.4 获取当前位姿并检查进展 <a class="header-anchor" href="#_5-4-获取当前位姿并检查进展" aria-label="Permalink to &quot;5.4 获取当前位姿并检查进展&quot;">​</a></h3><p><code>computeAndPublishVelocity()</code> 首先从 Costmap 获取当前机器人位姿。</p><p>获取失败会抛出 <code>PlannerException</code>，终止当前 Action。</p><p>随后调用 Progress Checker 的 <code>check(pose)</code>。如果机器人在允许时间内没有达到最小移动量，同样抛出异常，最终使 FollowPath 失败。</p><h3 id="_5-5-读取当前速度并调用-controller" tabindex="-1">5.5 读取当前速度并调用 Controller <a class="header-anchor" href="#_5-5-读取当前速度并调用-controller" aria-label="Permalink to &quot;5.5 读取当前速度并调用 Controller&quot;">​</a></h3><p>服务器从 <code>/odom</code> 取得速度，应用三个最小速度阈值，再调用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">controller-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">computeVelocityCommands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  current_pose,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  thresholded_odom_velocity,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  current_goal_checker);</span></span></code></pre></div><p>Controller 同时拥有已设置的 Path、TF Buffer 和 Local Costmap，因此能把路径、位姿、速度和障碍信息合成下一帧速度命令。</p><h3 id="_5-6-发布反馈和速度" tabindex="-1">5.6 发布反馈和速度 <a class="header-anchor" href="#_5-6-发布反馈和速度" aria-label="Permalink to &quot;5.6 发布反馈和速度&quot;">​</a></h3><p>计算成功后，服务器更新“最近一次有效速度指令时间”，计算剩余路径长度和指令速度，发布 Action Feedback，再发布 <code>cmd_vel</code>。</p><h3 id="_5-7-判断是否到达" tabindex="-1">5.7 判断是否到达 <a class="header-anchor" href="#_5-7-判断是否到达" aria-label="Permalink to &quot;5.7 判断是否到达&quot;">​</a></h3><p><code>isGoalReached()</code> 再次获取机器人位姿，读取阈值处理后的 Odom 速度，把路径终点转换到 Costmap Global Frame，最后调用当前 Goal Checker 的 <code>isGoalReached()</code>。</p><p>未到达则等待下一控制周期；到达则跳出循环，根据 <code>publish_zero_velocity</code> 决定是否发布零速度，并把 Action 标记为成功。</p><hr><h2 id="六、第三层状态-followpath-的执行、抢占、取消和失败" tabindex="-1">六、第三层状态：FollowPath 的执行、抢占、取消和失败 <a class="header-anchor" href="#六、第三层状态-followpath-的执行、抢占、取消和失败" aria-label="Permalink to &quot;六、第三层状态：FollowPath 的执行、抢占、取消和失败&quot;">​</a></h2><p>Lifecycle ACTIVE 只说明服务器可以工作，并不代表当前一定有控制任务。每个 FollowPath Goal 还有自己的运行状态。</p><p><img src="`+s+'" alt="图 6：FollowPath 运行状态、抢占与失败收口"></p><h3 id="_6-1-正常成功" tabindex="-1">6.1 正常成功 <a class="header-anchor" href="#_6-1-正常成功" aria-label="Permalink to &quot;6.1 正常成功&quot;">​</a></h3><p>Goal Checker 返回 true 后，控制循环结束。<code>publish_zero_velocity=true</code> 时先发布零速度，再调用 <code>succeeded_current()</code>，当前 Goal 进入 SUCCEEDED。</p><h3 id="_6-2-客户端取消" tabindex="-1">6.2 客户端取消 <a class="header-anchor" href="#_6-2-客户端取消" aria-label="Permalink to &quot;6.2 客户端取消&quot;">​</a></h3><p>循环检测到取消请求后，会调用 <code>terminate_all()</code> 并发布零速度。</p><p><code>SimpleActionServer</code> 看到 Goal Handle 正处于 canceling，会把它标记为 CANCELED；如果还有 Pending Goal，也一并终止。</p><h3 id="_6-3-新目标抢占" tabindex="-1">6.3 新目标抢占 <a class="header-anchor" href="#_6-3-新目标抢占" aria-label="Permalink to &quot;6.3 新目标抢占&quot;">​</a></h3><p>新 Goal 先进入 Pending。控制循环接受它时，<code>SimpleActionServer::accept_pending_goal()</code> 会把旧 Goal 标记为 ABORTED，再让新 Goal 成为 current。</p><p>因此抢占在服务器内部表现为“控制循环不中断地切换路径”，但从客户端看，旧 Goal 的终态是 ABORTED，不是 CANCELED。</p><h3 id="_6-4-controller-暂时算不出速度" tabindex="-1">6.4 Controller 暂时算不出速度 <a class="header-anchor" href="#_6-4-controller-暂时算不出速度" aria-label="Permalink to &quot;6.4 Controller 暂时算不出速度&quot;">​</a></h3><p>Controller 的 <code>computeVelocityCommands()</code> 抛出 <code>PlannerException</code> 时，处理方式由 <code>failure_tolerance</code> 决定：</p><ul><li><code>0</code>：立即向上抛出，FollowPath 失败。</li><li>大于 <code>0</code>：先输出零速度，在容忍时间内允许后续周期恢复。</li><li><code>-1</code>：不因 Controller 耐心超时而失败，持续允许零速度等待。</li></ul><p>即使设为 <code>-1</code>，也不代表任务永远不会失败。Progress Checker 仍可能因为长期无进展终止任务，TF 位姿获取失败和其他异常也仍会中止 Action。</p><h3 id="_6-5-明确失败入口" tabindex="-1">6.5 明确失败入口 <a class="header-anchor" href="#_6-5-明确失败入口" aria-label="Permalink to &quot;6.5 明确失败入口&quot;">​</a></h3><p>当前实现的主要 ABORTED 入口包括：</p><ul><li><code>controller_id</code> 不存在。</li><li><code>goal_checker_id</code> 不存在。</li><li>输入 Path 为空。</li><li>无法从 TF／Costmap 获取机器人位姿。</li><li>Progress Checker 判定长期无进展。</li><li>Controller 连续异常超过 <code>failure_tolerance</code>。</li><li>Controller 或其他调用抛出未恢复异常。</li></ul><p>这些失败只负责结束 FollowPath。是否清 Costmap、重新规划、后退或等待，由上层行为树或自研规控状态机决定。</p><hr><h2 id="七、动态参数-为什么导航过程中有些参数改不了" tabindex="-1">七、动态参数：为什么导航过程中有些参数改不了 <a class="header-anchor" href="#七、动态参数-为什么导航过程中有些参数改不了" aria-label="Permalink to &quot;七、动态参数：为什么导航过程中有些参数改不了&quot;">​</a></h2><p>Controller Server 自己注册动态参数回调，支持运行时更新：</p><ul><li><code>controller_frequency</code>。</li><li><code>min_x_velocity_threshold</code>。</li><li><code>min_y_velocity_threshold</code>。</li><li><code>min_theta_velocity_threshold</code>。</li><li><code>failure_tolerance</code>。</li></ul><p>但 <code>computeControl()</code> 在整个 FollowPath 执行期间持有 <code>dynamic_params_lock_</code>。服务器级回调使用 <code>try_lock()</code>，所以导航正在运行时修改这些顶层参数会被拒绝，而不是在控制循环中途改变频率或阈值。</p><p>名字中含 <code>.</code> 的插件参数会被服务器级回调跳过，由各插件自己的动态参数回调处理，例如：</p><ul><li><code>progress_checker.required_movement_radius</code>。</li><li><code>general_goal_checker.xy_goal_tolerance</code>。</li><li><code>general_goal_checker.yaw_goal_tolerance</code>。</li></ul><p>这形成了两层参数所有权：服务器只管理控制框架参数，插件管理自己的算法参数。</p><hr><h2 id="八、源码函数地图-从入口到收口分别在哪里" tabindex="-1">八、源码函数地图：从入口到收口分别在哪里 <a class="header-anchor" href="#八、源码函数地图-从入口到收口分别在哪里" aria-label="Permalink to &quot;八、源码函数地图：从入口到收口分别在哪里&quot;">​</a></h2><p>如果要读源码，可以按下面顺序追踪。</p><h3 id="_8-1-节点入口" tabindex="-1">8.1 节点入口 <a class="header-anchor" href="#_8-1-节点入口" aria-label="Permalink to &quot;8.1 节点入口&quot;">​</a></h3><ul><li><code>src/main.cpp</code>：初始化 ROS 2 和日志，创建 <code>ControllerServer</code> 并 Spin。</li></ul><h3 id="_8-2-lifecycle-与资源创建" tabindex="-1">8.2 Lifecycle 与资源创建 <a class="header-anchor" href="#_8-2-lifecycle-与资源创建" aria-label="Permalink to &quot;8.2 Lifecycle 与资源创建&quot;">​</a></h3><ul><li><code>ControllerServer::ControllerServer()</code>：声明参数、创建 Local Costmap 对象。</li><li><code>on_configure()</code>：配置 Costmap、加载插件、创建通信接口。</li><li><code>on_activate()</code>：激活资源和 Bond。</li><li><code>on_deactivate()</code>：停止任务并发布零速度。</li><li><code>on_cleanup()</code>：释放插件和 ROS 接口。</li></ul><h3 id="_8-3-action-主链" tabindex="-1">8.3 Action 主链 <a class="header-anchor" href="#_8-3-action-主链" aria-label="Permalink to &quot;8.3 Action 主链&quot;">​</a></h3><ul><li><code>computeControl()</code>：FollowPath 总循环。</li><li><code>findControllerId()</code>：选择 Controller。</li><li><code>findGoalCheckerId()</code>：选择 Goal Checker。</li><li><code>setPlannerPath()</code>：下发路径并保存终点。</li><li><code>updateGlobalPath()</code>：处理 Pending Goal 和新路径。</li><li><code>computeAndPublishVelocity()</code>：生成反馈和速度。</li><li><code>isGoalReached()</code>：执行最终到达判定。</li></ul><h3 id="_8-4-输入输出辅助" tabindex="-1">8.4 输入输出辅助 <a class="header-anchor" href="#_8-4-输入输出辅助" aria-label="Permalink to &quot;8.4 输入输出辅助&quot;">​</a></h3><ul><li><code>getRobotPose()</code>：通过 Costmap 获取当前位姿。</li><li><code>speedLimitCallback()</code>：把限速同步给所有 Controller。</li><li><code>publishVelocity()</code>：检查 Lifecycle 和订阅者后发布速度。</li><li><code>publishZeroVelocity()</code>：构造并发布零速度。</li><li><code>dynamicParametersCallback()</code>：更新服务器级动态参数。</li></ul><h3 id="_8-5-包内插件实现" tabindex="-1">8.5 包内插件实现 <a class="header-anchor" href="#_8-5-包内插件实现" aria-label="Permalink to &quot;8.5 包内插件实现&quot;">​</a></h3><ul><li><code>simple_progress_checker.cpp</code>。</li><li><code>pose_progress_checker.cpp</code>。</li><li><code>simple_goal_checker.cpp</code>。</li><li><code>stopped_goal_checker.cpp</code>。</li><li><code>position_goal_checker.cpp</code>。</li></ul><hr><h2 id="九、调试时最值得先看的八个点" tabindex="-1">九、调试时最值得先看的八个点 <a class="header-anchor" href="#九、调试时最值得先看的八个点" aria-label="Permalink to &quot;九、调试时最值得先看的八个点&quot;">​</a></h2><h3 id="_9-1-有路径但没有速度" tabindex="-1">9.1 有路径但没有速度 <a class="header-anchor" href="#_9-1-有路径但没有速度" aria-label="Permalink to &quot;9.1 有路径但没有速度&quot;">​</a></h3><p>先确认 Controller Server 是 ACTIVE，再检查 <code>cmd_vel</code> 是否被 Launch 重映射，以及速度 Publisher 是否真的有订阅者。</p><h3 id="_9-2-一直等待-不进入-controller" tabindex="-1">9.2 一直等待，不进入 Controller <a class="header-anchor" href="#_9-2-一直等待-不进入-controller" aria-label="Permalink to &quot;9.2 一直等待，不进入 Controller&quot;">​</a></h3><p>检查 <code>local_costmap</code> 是否 Current。传感器、TF 或 Costmap 更新异常都会让控制循环停在地图等待阶段。</p><h3 id="_9-3-很快报-failed-to-make-progress" tabindex="-1">9.3 很快报“Failed to make progress” <a class="header-anchor" href="#_9-3-很快报-failed-to-make-progress" aria-label="Permalink to &quot;9.3 很快报“Failed to make progress”&quot;">​</a></h3><p>核对 <code>required_movement_radius</code> 和 <code>movement_time_allowance</code> 是否适合车辆速度。低速车在短窗口内达不到较大半径，会被误判为卡住。</p><h3 id="_9-4-到目标附近反复前后修正" tabindex="-1">9.4 到目标附近反复前后修正 <a class="header-anchor" href="#_9-4-到目标附近反复前后修正" aria-label="Permalink to &quot;9.4 到目标附近反复前后修正&quot;">​</a></h3><p>检查 Goal Checker 的 <code>stateful</code>。启用后，XY 达标后不会在最终旋转阶段反复退回位置判定。</p><h3 id="_9-5-只想走到位置-不关心朝向" tabindex="-1">9.5 只想走到位置，不关心朝向 <a class="header-anchor" href="#_9-5-只想走到位置-不关心朝向" aria-label="Permalink to &quot;9.5 只想走到位置，不关心朝向&quot;">​</a></h3><p>选择 <code>PositionGoalChecker</code>，不要靠把 Yaw 容差设置得极大来模拟“忽略朝向”。前者的语义更直接。</p><h3 id="_9-6-目标已进入容差-但-action-仍不成功" tabindex="-1">9.6 目标已进入容差，但 Action 仍不成功 <a class="header-anchor" href="#_9-6-目标已进入容差-但-action-仍不成功" aria-label="Permalink to &quot;9.6 目标已进入容差，但 Action 仍不成功&quot;">​</a></h3><p>如果使用 <code>StoppedGoalChecker</code>，还必须满足平移和旋转速度阈值。此时要同时检查 Odom 和三个最小速度阈值。</p><h3 id="_9-7-feedback-的速度与实车速度不一致" tabindex="-1">9.7 Feedback 的速度与实车速度不一致 <a class="header-anchor" href="#_9-7-feedback-的速度与实车速度不一致" aria-label="Permalink to &quot;9.7 Feedback 的速度与实车速度不一致&quot;">​</a></h3><p>这是设计行为。Feedback 的 <code>speed</code> 是 Controller 输出命令，不是 Odom 测量值。</p><h3 id="_9-8-抢占后旧客户端收到-aborted" tabindex="-1">9.8 抢占后旧客户端收到 ABORTED <a class="header-anchor" href="#_9-8-抢占后旧客户端收到-aborted" aria-label="Permalink to &quot;9.8 抢占后旧客户端收到 ABORTED&quot;">​</a></h3><p>当前 <code>SimpleActionServer</code> 接受 Pending Goal 时会 Abort 旧 Goal。这不是控制循环崩溃，而是当前版本的抢占终态语义。</p><hr><h2 id="十、把整个包压缩成一句话" tabindex="-1">十、把整个包压缩成一句话 <a class="header-anchor" href="#十、把整个包压缩成一句话" aria-label="Permalink to &quot;十、把整个包压缩成一句话&quot;">​</a></h2><p><code>nav2_controller</code> 做的事情可以概括为：</p><blockquote><p>用 Lifecycle 管理一套可插拔的局部控制运行时，通过 FollowPath 接收 Path 和插件选择，融合 Local Costmap、TF、Odom 与 Speed Limit，循环生成 cmd_vel，并用 Progress Checker 和 Goal Checker把“卡住”与“到达”变成明确的 Action 终态。</p></blockquote><p>理解这句话，就能把 Controller Server、局部控制算法、进度检查、目标检查和上层恢复机制准确地拆开。</p><p>路径只是意图，速度才是执行。而 <code>nav2_controller</code>，就是 Nav2 从意图走向运动的那一层。</p>',246)])])}const f=o(p,[["render",_]]);export{g as __pageData,f as default};
